package com.farika.soundflow;
import android.app.Application;import android.content.*;import android.net.Uri;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAudio168Test {
 Context c;SyntheticStore store;
 public static class SyntheticStore extends LocalAudioStore {
  static Map<String,Access> access=new HashMap<>();static Map<String,Metadata> metas=new HashMap<>();static Set<String> grants=new HashSet<>();static int deletes,releases,takeFlags;static boolean allow=true,denied=false,failMetadata=false;static long clock=100;
  SyntheticStore(Context c){super(c);}static void reset(){access.clear();metas.clear();grants.clear();deletes=releases=takeFlags=0;allow=true;denied=failMetadata=false;clock=100;}
  protected long now(){return clock++;}protected boolean persistentRead(Uri u){return grants.contains(u.toString());}protected void take(Uri u,int f){takeFlags=f&(READ|WRITE);grants.add(u.toString());}protected void release(Uri u){releases++;grants.remove(u.toString());}
  protected Metadata metadata(Uri u)throws Exception{if(failMetadata)throw new IOException("Synthetic metadata unavailable");return metas.containsKey(u.toString())?metas.get(u.toString()):new Metadata(u.getLastPathSegment(),"Local",180000);}
  public Access probe(Entry e){return access.getOrDefault(e.document,Access.AVAILABLE);}protected boolean deleteDocument(Uri u){deletes++;if(denied)throw new SecurityException("Synthetic provider denied");return allow;}
 }
 @Before public void setup(){c=RuntimeEnvironment.getApplication();SyntheticStore.reset();store=new SyntheticStore(c);PlaybackService.instance=null;}
 @After public void cleanup(){PlaybackService.instance=null;}
 LocalAudioStore.Entry add(String name)throws Exception{return store.add(Uri.parse("content://synthetic.audio/"+name),LocalAudioStore.READ|LocalAudioStore.WRITE);}
 @Test public void referencesAndIndependentPositionsSurviveReopen()throws Exception{LocalAudioStore.Entry a=add("a"),b=add("b");store.position(a.uri(),42000,180000);store.position(b.uri(),7000,180000);LocalAudioStore again=new LocalAudioStore(c);assertEquals("content://synthetic.audio/a",again.get(a.uri()).document);assertEquals(42000,again.get(a.uri()).position);assertEquals(7000,again.get(b.uri()).position);assertEquals(0,c.getFilesDir().list().length);}
 @Test public void duplicateKeepsIdDateAndBookmark()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),42000,180000);SyntheticStore.metas.put(a.document,new LocalAudioStore.Metadata("New title","Artist",150000));LocalAudioStore.Entry b=add("a");assertEquals(a.id,b.id);assertEquals(a.addedAt,b.addedAt);assertEquals(42000,b.position);assertEquals("New title",b.title);assertEquals(1,store.list(LocalAudioStore.Sort.NEWEST).size());}
 @Test public void equalNamesDoNotMergeDifferentDocuments()throws Exception{SyntheticStore.metas.put("content://synthetic.audio/a",new LocalAudioStore.Metadata("Same","A",1000));SyntheticStore.metas.put("content://synthetic.audio/b",new LocalAudioStore.Metadata("Same","A",1000));assertNotEquals(add("a").id,add("b").id);}
 @Test public void takesOnlyGrantedReadWriteFlags()throws Exception{store.add(Uri.parse("content://synthetic.audio/a"),LocalAudioStore.READ|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);assertEquals(LocalAudioStore.READ,SyntheticStore.takeFlags);}
 @Test public void noDurableReadRejectsReference()throws Exception{try{store.add(Uri.parse("content://synthetic.audio/a"),0);fail();}catch(IOException expected){}assertTrue(store.list(LocalAudioStore.Sort.NEWEST).isEmpty());}
 @Test public void rejectsRawFilePaths()throws Exception{try{store.add(Uri.parse("file:///a.mp3"),LocalAudioStore.READ);fail();}catch(IOException expected){}assertEquals(0,SyntheticStore.takeFlags);}
 @Test public void failedImportReleasesNewGrant()throws Exception{SyntheticStore.failMetadata=true;try{add("a");fail();}catch(IOException expected){}assertEquals(1,SyntheticStore.releases);assertTrue(SyntheticStore.grants.isEmpty());}
 @Test public void failedRefreshRetainsExistingGrantAndRow()throws Exception{LocalAudioStore.Entry a=add("a");SyntheticStore.failMetadata=true;try{add("a");fail();}catch(IOException expected){}assertNotNull(store.get(a.uri()));assertTrue(SyntheticStore.grants.contains(a.document));assertEquals(0,SyntheticStore.releases);}
 @Test public void sortsByAddedDateAndRussianTitle()throws Exception{LocalAudioStore.Entry z=add("Яблоко"),a=add("абрикос"),b=add("Банан");assertEquals(b.uri(),store.list(LocalAudioStore.Sort.NEWEST).get(0).uri());assertEquals(z.uri(),store.list(LocalAudioStore.Sort.OLDEST).get(0).uri());List<LocalAudioStore.Entry> title=store.list(LocalAudioStore.Sort.TITLE);assertEquals(a.uri(),title.get(0).uri());assertEquals(b.uri(),title.get(1).uri());assertEquals(z.uri(),title.get(2).uri());}
 @Test public void clampsAndNeverResurrectsDeletedBookmark()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),999999,10000);assertEquals(10000,store.get(a.uri()).position);store.position(a.uri(),-2,10000);assertEquals(0,store.get(a.uri()).position);store.remove(a.uri());store.position(a.uri(),4000,10000);assertNull(store.get(a.uri()));}
 @Test public void removalOnlyUnlinksWithoutDeletingSource()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),2000,180000);store.remove(a.uri());assertNull(store.get(a.uri()));assertEquals(0,SyntheticStore.deletes);assertEquals(1,SyntheticStore.releases);assertEquals(LocalAudioStore.Access.AVAILABLE,SyntheticStore.access.getOrDefault(a.document,LocalAudioStore.Access.AVAILABLE));}
 @Test public void successfulSourceDeleteAlsoDropsBookmark()throws Exception{LocalAudioStore.Entry a=add("a");store.deleteFile(a.uri());assertNull(store.get(a.uri()));assertEquals(1,SyntheticStore.deletes);}
 @Test public void failedSourceDeleteRetainsBookmark()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),23000,180000);SyntheticStore.allow=false;try{store.deleteFile(a.uri());fail();}catch(IOException expected){}assertEquals(23000,store.get(a.uri()).position);assertEquals(0,SyntheticStore.releases);}
 @Test public void securityFailureRetainsBookmark()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),23000,180000);SyntheticStore.denied=true;try{store.deleteFile(a.uri());fail();}catch(SecurityException expected){}assertEquals(23000,store.get(a.uri()).position);}
 @Test public void scanRemovesOnlyConfirmedMissing()throws Exception{LocalAudioStore.Entry a=add("a"),b=add("b"),d=add("d");SyntheticStore.access.put(a.document,LocalAudioStore.Access.MISSING);SyntheticStore.access.put(b.document,LocalAudioStore.Access.UNAVAILABLE);SyntheticStore.access.put(d.document,LocalAudioStore.Access.NO_PERMISSION);LocalAudioStore.Scan scan=store.scan(LocalAudioStore.Sort.NEWEST,()->{});assertEquals(Arrays.asList(a.uri()),scan.removed);assertEquals(2,scan.unavailable);assertNull(store.get(a.uri()));assertNotNull(store.get(b.uri()));assertNotNull(store.get(d.uri()));}
 @Test public void scanCanBeCancelledBeforeDestructiveProbe()throws Exception{LocalAudioStore.Entry a=add("a");SyntheticStore.access.put(a.document,LocalAudioStore.Access.MISSING);try{store.scan(LocalAudioStore.Sort.NEWEST,()->{throw new InterruptedIOException();});fail();}catch(InterruptedIOException expected){}assertNotNull(store.get(a.uri()));}
 @Test public void selectedRemovalResetsGlobalBookmarkAndIntent()throws Exception{LocalAudioStore.Entry a=add("a"),b=add("b");PlaybackCheckpoint.save(c,Arrays.asList(a.uri(),b.uri()),0,42000,false,false,true,false,true,false);store.remove(a.uri());PlaybackCheckpoint.Snapshot s=PlaybackCheckpoint.read(c);assertEquals(b.uri(),s.current());assertEquals(0,s.position);assertFalse(s.wanted);store.remove(b.uri());assertNull(PlaybackCheckpoint.read(c));}
 @Test public void nonSelectedRemovalRetainsCurrentGlobalPosition()throws Exception{LocalAudioStore.Entry a=add("a"),b=add("b");PlaybackCheckpoint.save(c,Arrays.asList(a.uri(),b.uri()),1,42000,false,false,true,false,true,false);store.remove(a.uri());PlaybackCheckpoint.Snapshot s=PlaybackCheckpoint.read(c);assertEquals(b.uri(),s.current());assertEquals(42000,s.position);assertTrue(s.wanted);}
 @Test public void localLibraryLookupAndRepeatContextWorkWithoutLogin()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),8000,180000);Library l=new Library(c);assertEquals(8000,l.find(a.uri()).savedPosition);l.upsert(a.track());l.save();assertTrue(new Library(c).tracks.isEmpty());assertTrue(RepeatPolicy.listContext("own"));assertNull(new Library(c).find("local:missing"));}
 @Test public void readdingRemovedReferenceStartsFresh()throws Exception{LocalAudioStore.Entry a=add("a");store.position(a.uri(),8000,180000);store.remove(a.uri());LocalAudioStore.Entry b=add("a");assertNotEquals(a.id,b.id);assertEquals(0,b.position);}
 @Test public void successfulRemovalBroadcastsExactReference()throws Exception{LocalAudioStore.Entry a=add("a");store.remove(a.uri());boolean seen=false;for(Intent event:Shadows.shadowOf((Application)c).getBroadcastIntents())if(LocalAudioStore.EVENT.equals(event.getAction())){assertEquals(c.getPackageName(),event.getPackage());assertEquals(a.uri(),event.getStringExtra("removed"));seen=true;}assertTrue(seen);}
}
